      //                     && (ask_no as i64) <= limits.max_trade_price\n                                    //                 {\n                                    //                     if ask_no - best_no_bid as i64 <= 4 {\n                                    //                         if !no_bought && !stop_trading {\n                                    //                             no_count = 100;\n                                    //                             total_no_cost = 100 * ask_no;\n                                    //                             avg_no_cost = ask_no as f64;\n                                    //                             need_to_sell_no = true;\n                                    //                             no_buy_fee = kalshi_fee_exact(\n                                    //                                 avg_no_cost.round() as u16,\n                                    //                             );\n                                    //                             avg_no_cost += no_buy_fee;\n                                    //                             no_bought = true;\n                                    //                             println!(\"Bought NO at {}\", ask_no);\n                                    //                         }\n                                    //                     }\n                                    //                 }\n                                    //             } else {\n                                    //                 println!(\"   \ud83d\uded1 Skipping NO buy due to Buy Pressure (Whale/OBI)\");\n                                    //             }\n                                    //         }\n                                    //     }\n                                    // }\n\n                                    if !whale_sell_active && current_obi > -0.5 {\n                                        // Standard Buy Logic\n                                        if ask_yes >= 96 // High probability buying only\n                                            && (ask_yes as i64) <= limits.max_trade_price\n                                        {\n                                            if ask_yes - best_yes_bid as i64 <= 4 {\n                                                if !yes_bought && !stop_trading {\n                                                    yes_count = 100;\n                                                    total_yes_cost = 100 * ask_yes;\n                                                    avg_yes_cost = ask_yes as f64;\n                                                    yes_buy_fee = kalshi_fee_exact(\n                                                        avg_yes_cost.round() as u16,\n                                                    );\n                                                    avg_yes_cost += yes_buy_fee;\n                                                    need_to_sell_yes = true;\n                                                    yes_bought = true;\n                                                    println!(\"Bought YES at {}\", ask_yes);\n                                                }\n                                            }\n                                        }\n                                    } else {\n                                        println!(\"   \ud83d\uded1 Skipping YES buy due to Sell Pressure (Whale/OBI)\");\n                                    }\n                                    if !whale_buy_active && current_obi < 0.5 {\n                                        // Standard Buy Logic\n                                        if ask_no >= 96 && (ask_no as i64) <= limits.max_trade_price\n                                        {\n                                            if ask_no - best_no_bid as i64 <= 4 {\n                                                if !no_bought && !stop_trading {\n                                                    no_count = 100;\n                                                    total_no_cost = 100 * ask_no;\n                                                    avg_no_cost = ask_no as f64;\n                                                    need_to_sell_no = true;\n                                                    no_buy_fee = kalshi_fee_exact(\n                                                        avg_no_cost.round() as u16,\n                                                    );\n                                                    avg_no_cost += no_buy_fee;\n                                                    no_bought = true;\n                                                    println!(\"Bought NO at {}\", ask_no);\n                                                }\n                                            }\n                                        }\n                                    } else {\n                                        println!(\n                                            \"   \ud83d\uded1 Skipping NO buy due to Buy Pressure (Whale/OBI)\"\n                                        );\n                                    }\n\n                                    // SELL LOGIC (Updated with OBI Panic)\n                                    // Pre-emptive Sell if OBI indicates impending move against us\n\n                                    if need_to_sell_yes {\n                                        // User's defined complex logic\n                                        let profit_target_hit = avg_yes_cost > 90.00\n                                            && best_yes_bid as f64 >= avg_yes_cost + 2.00;\n\n                                        // Panic trigger:\n                                        // 1. Whale Sell Active\n                                        // 2. OBI < -0.7 (Massive Sell Pressure)\n                                        let panic_sell = (whale_sell_active || current_obi < -0.7)\n                                            && best_yes_bid > 0;\n\n                                        if profit_target_hit || panic_sell {\n                                            if panic_sell {\n                                                println!(\"   \ud83d\udea8 PANIC SELLING YES (OBI: {:.2} | Whale: {})\", current_obi, whale_sell_active);\n                                            }\n                                            need_to_sell_yes = false;\n                                            stop_trading = true;\n                                            println!(\"Sold YES at {}\", best_yes_bid);\n\n                                            yes_sell_fee = kalshi_fee_exact(best_yes_bid as u16);\n                                            profit = (best_yes_bid as f64 - yes_sell_fee)\n                                                - (avg_yes_cost);\n\n                                            if let Err(e) = log_trade_to_csv(\n                                                &target.market_ticker,\n                                                \"yes\",\n                                                avg_yes_cost,\n                                                best_yes_bid,\n                                                profit,\n                                            ) {\n                                                error!(\"Failed to log trade: {}\", e);\n                                            }\n                                        }\n                                    }\n                                    if need_to_sell_no {\n                                        let profit_target_hit = (avg_no_cost > 90.00\n                                            && best_no_bid as f64 >= avg_no_cost + 2.00);\n\n                                        // Panic trigger: OBI > 0.7 (Massive Buy Pressure)\n                                        let panic_sell = (whale_buy_active || current_obi > 0.7)\n                                            && best_no_bid > 0;\n\n                                        if profit_target_hit || panic_sell {\n                                            if panic_sell {\n                                                println!(\"   \ud83d\udea8 PANIC SELLING NO (OBI: {:.2} | Whale: {})\", current_obi, whale_buy_active);\n                                            }\n                                            need_to_sell_no = false;\n                                            stop_trading = true;\n                                            println!(\"Sold NO at {}\", best_no_bid);\n\n                                            no_sell_fee = kalshi_fee_exact(best_no_bid as u16);\n                                            profit =\n                                                (best_no_bid as f64 - no_sell_fee) - (avg_no_cost);\n\n                                            if let Err(e) = log_trade_to_csv(\n                                                &target.market_ticker,\n                                                \"no\",\n                                                avg_no_cost,\n                                                best_no_bid,\n                                                profit,\n                                            ) {\n                                                error!(\"Failed to log trade: {}\", e);\n                                            }\n                                        }\n                                    }\n                                }\n\n                                println!(\"---------------------------------------------------\");\n                            }\n                        }\n\n    // Stranded log logic\n    if need_to_sell_yes {\n        println!(\"\u26a0\ufe0f Market ended with unsold YES position. Logging loss.\");\n        let buy_fee = kalshi_fee_exact(avg_yes_cost.round() as u16);\n        let profit = -(avg_yes_cost + buy_fee);\n        if let Err(e) = log_trade_to_csv(&target.market_ticker, \"yes\", avg_yes_cost, 0, profit) {\n            error!(\"Failed to log stranded trade: {}\", e);\n        }\n    }\n    if need_to_sell_no {\n        println!(\"\u26a0\ufe0f Market ended with unsold NO position. Logging loss.\");\n        let buy_fee = kalshi_fee_exact(avg_no_cost.round() as u16);\n        let profit = -(avg_no_cost + buy_fee);\n        if let Err(e) = log_trade_to_csv(&target.market_ticker, \"no\", avg_no_cost, 0, profit) {\n            error!(\"Failed to log stranded trade: {}\", e);\n        }\n    }\n\n    Ok(())\n}\n"
